parameters.functionCode:
// Validate required fields
const requiredFields = ['address', 'income', 'householdSize'];
const missingFields = [];

for (const field of requiredFields) {
  if (!$json.body[field]) {
    missingFields.push(field);
  }
}

if (missingFields.length > 0) {
  return [{
    json: {
      error: true,
      message: `Missing required fields: ${missingFields.join(', ')}`,
      statusCode: 400
    }
  }];
}

// Sanitize inputs
const data = {
  address: $json.body.address.trim(),
  income: parseFloat($json.body.income),
  householdSize: parseInt($json.body.householdSize),
  email: $json.body.email?.trim() || '',
  name: $json.body.name?.trim() || 'Applicant'
};

// Validate income and household size
if (isNaN(data.income) || data.income <= 0) {
  return [{
    json: {
      error: true,
      message: 'Invalid income value',
      statusCode: 400
    }
  }];
}

if (isNaN(data.householdSize) || data.householdSize < 1 || data.householdSize > 8) {
  return [{
    json: {
      error: true,
      message: 'Household size must be between 1 and 8',
      statusCode: 400
    }
  }];
}

return [{ json: data }];

// Rural area - eligible to proceed
return [{
  json: {
    ...($node["Validate Input"].json),
    ruralStatus: 'eligible',
    ruralEligible: true
  }
}];

// Not rural area - ineligible
return [{
  json: {
    ...($node["Validate Input"].json),
    ruralStatus: 'ineligible',
    ruralEligible: false,
    reason: 'Property is not in a USDA-eligible rural area',
    alternatives: ['FHA loans', 'Conventional loans', 'VA loans (if veteran)']
  }
}];

// Extract state and county from geocoding result
const addressComponents = $json.results[0].address_components;

let state = '';
let county = '';

for (const component of addressComponents) {
  if (component.types.includes('administrative_area_level_1')) {
    state = component.long_name;
  }
  if (component.types.includes('administrative_area_level_2')) {
    county = component.long_name.replace(' County', '');
  }
}

return [{
  json: {
    ...($node["Set Rural Eligible"].json),
    state: state,
    county: county
  }
}];

// Compare user income to USDA limit
const householdSize = $json.householdSize;
const userIncome = $json.income;

// Determine which income limit applies
const incomeLimit = householdSize <= 4 
  ? $json.income_limit_1_4 
  : $json.income_limit_5_8;

const isEligible = userIncome <= incomeLimit;
const incomePercentage = (userIncome / incomeLimit * 100).toFixed(1);

return [{
  json: {
    ...($json),
    incomeLimit: incomeLimit,
    userIncome: userIncome,
    incomeEligible: isEligible,
    incomePercentage: incomePercentage,
    overBy: isEligible ? 0 : userIncome - incomeLimit
  }
}];

// Generate eligibility report
const data = $json;

const report = {
  applicantName: data.name,
  address: data.address,
  state: data.state,
  county: data.county,
  householdSize: data.householdSize,
  userIncome: data.userIncome,
  incomeLimit: data.incomeLimit,
  incomePercentage: data.incomePercentage,

  // Overall eligibility
  overallEligible: data.ruralEligible && data.incomeEligible,

  // Status breakdown
  ruralStatus: data.ruralEligible ? 'ELIGIBLE' : 'INELIGIBLE',
  incomeStatus: data.incomeEligible ? 'ELIGIBLE' : 'INELIGIBLE',

  // Next steps
  nextSteps: [],
  documentChecklist: [
    '2 years of tax returns (Form 1040)',
    '2 months of pay stubs (all household earners)',
    '2 months of bank statements (all accounts)',
    'Credit report (will be pulled by lender)',
    'Photo ID (driver\'s license or passport)',
    'Social Security card',
    'Proof of citizenship (if applicable)'
  ],

  // Recommendations
  recommendations: []
};

if (report.overallEligible) {
  report.nextSteps = [
    '1. Gather required documents (see checklist)',
    '2. Contact a USDA-approved lender for pre-qualification',
    '3. Get pre-approved (soft credit check, no commitment)',
    '4. Start house hunting in your eligible area',
    '5. Make an offer and begin the underwriting process'
  ];
  report.recommendations = [
    'Contact a local credit union or rural bank (often best USDA rates)',
    'Consider working with a loan packager to streamline the process',
    'Ask about USDA Direct Loan if income is below 80% area median'
  ];
} else if (!data.ruralEligible) {
  report.nextSteps = [
    'Property is not in a USDA-eligible rural area',
    'Consider these alternatives:',
    '  - FHA loans (3.5% down, more flexible credit)',
    '  - Conventional loans (3-5% down, good credit required)',
    '  - VA loans (0% down, veterans only)',
    'Or look for properties in nearby USDA-eligible areas'
  ];
} else if (!data.incomeEligible) {
  report.nextSteps = [
    `Income ($${data.userIncome.toLocaleString()}) exceeds limit ($${data.incomeLimit.toLocaleString()})`,
    'Consider these options:',
    '  - Lower-income spouse applies alone (other added to title later)',
    '  - Look for nearby counties with higher income limits',
    '  - FHA/Conventional loans have no income limits (only DTI matters)',
    '  - If self-employed, maximize business deductions to lower AGI'
  ];
  report.recommendations = [
    `You are ${data.incomePercentage}% of the income limit (over by $${data.overBy.toLocaleString()})`,
    'Talk to a tax professional about strategies to lower adjusted gross income'
  ];
}

return [{ json: report }];

