={{ JSON.stringify({
  success: true,
  message: 'Eligibility report generated',
  eligible: $json.overallEligible,
  report: $json
}) }}

={{ JSON.stringify({
  success: true,
  message: 'Property not in USDA-eligible area',
  eligible: false,
  ruralStatus: 'ineligible',
  alternatives: $json.alternatives
}) }}
